#include "../src/core/crsf.h"
#include "tinytest.h"

/* RC frame for channels {172,992,1811,1234,191,1792,992,992,0,2047,1,1024,
 * 500,1500,1700,999}, generated by an independent Python packer. */
static const uint8_t rc_frame[26] = {
    0xC8, 0x18, 0x16, 0xAC, 0x00, 0xDF, 0xC4, 0xA5, 0xF9, 0x0B, 0x80, 0x83, 0x0F,
    0x7C, 0x00, 0xF8, 0x7F, 0x00, 0x00, 0x48, 0x1F, 0xEE, 0x92, 0xFA, 0x7C, 0xAF};
static const uint16_t rc_expected[16] = {172, 992, 1811, 1234, 191, 1792, 992, 992,
                                         0, 2047, 1, 1024, 500, 1500, 1700, 999};
/* LINK_STATISTICS: rssi1 60, rssi2 70, lq 100, snr 10, ant 1, mode 4, pwr 3,
 * dl rssi 55, dl lq 98, dl snr 8 */
static const uint8_t ls_frame[14] = {0xC8, 0x0C, 0x14, 0x3C, 0x46, 0x64, 0x0A,
                                     0x01, 0x04, 0x03, 0x37, 0x62, 0x08, 0x70};

static void test_crc8_check_value(void)
{
    /* CRC-8/DVB-S2 catalogue check value */
    const uint8_t s[] = "123456789";
    CHECK_EQ_INT(crsf_crc8(s, 9), 0xBC);
}

static void test_parse_rc_frame(void)
{
    crsf_parser_t p;
    crsf_parser_init(&p);
    uint32_t t = 1000;
    /* garbage before the frame must be skipped */
    const uint8_t junk[] = {0x00, 0x55, 0x16, 0xFF};
    for (unsigned i = 0; i < sizeof(junk); i++) crsf_parse_byte(&p, junk[i], t++);
    uint8_t type = 0;
    for (int i = 0; i < 26; i++) type = crsf_parse_byte(&p, rc_frame[i], t++);
    CHECK_EQ_INT(type, CRSF_TYPE_RC_CHANNELS);
    CHECK(p.rc_fresh);
    for (int i = 0; i < 16; i++) CHECK_EQ_INT(p.channels[i], rc_expected[i]);
    CHECK_EQ_INT(p.frames_ok, 1);
    CHECK_NEAR(crsf_ch_to_us(172), 987.5, 1e-3);
    CHECK_NEAR(crsf_ch_to_us(992), 1500, 1e-3);
    CHECK_NEAR(crsf_ch_to_us(1811), 2011.875, 1e-3);
    CHECK_NEAR(crsf_ch_to_norm(1811), 1.0, 1e-6);
    CHECK_NEAR(crsf_ch_to_norm(172), -1.0, 2e-3);
}

static void test_crc_error_and_timeout(void)
{
    crsf_parser_t p;
    crsf_parser_init(&p);
    uint8_t bad[26];
    for (int i = 0; i < 26; i++) bad[i] = rc_frame[i];
    bad[10] ^= 0x01;
    uint32_t t = 0;
    for (int i = 0; i < 26; i++) CHECK_EQ_INT(crsf_parse_byte(&p, bad[i], t++), 0);
    CHECK_EQ_INT(p.crc_errors, 1);
    CHECK_EQ_INT(p.channels[0], CRSF_CH_MID); /* untouched */

    /* half a frame, then a 2 ms gap, then a complete frame */
    for (int i = 0; i < 10; i++) crsf_parse_byte(&p, rc_frame[i], t++);
    t += 2000;
    uint8_t type = 0;
    for (int i = 0; i < 26; i++) type = crsf_parse_byte(&p, rc_frame[i], t++);
    CHECK_EQ_INT(type, CRSF_TYPE_RC_CHANNELS);
    CHECK_EQ_INT(p.framing_errors, 1);

    /* invalid length byte resets */
    crsf_parse_byte(&p, 0xC8, t++);
    crsf_parse_byte(&p, 0x7F, t++);
    CHECK_EQ_INT(p.pos, 0);
}

static void test_link_stats(void)
{
    crsf_parser_t p;
    crsf_parser_init(&p);
    uint8_t type = 0;
    for (int i = 0; i < 14; i++) type = crsf_parse_byte(&p, ls_frame[i], (uint32_t)i);
    CHECK_EQ_INT(type, CRSF_TYPE_LINK_STATS);
    CHECK_EQ_INT(p.link.uplink_rssi1, 60);
    CHECK_EQ_INT(p.link.uplink_lq, 100);
    CHECK_EQ_INT(p.link.uplink_snr, 10);
    CHECK_EQ_INT(p.link.rf_mode, 4);
    CHECK_EQ_INT(p.link.downlink_lq, 98);
}

static void test_pack_roundtrip_and_builders(void)
{
    uint8_t frame[CRSF_MAX_FRAME];
    int n = crsf_build_rc_channels(frame, rc_expected);
    CHECK_EQ_INT(n, 26);
    for (int i = 0; i < 26; i++) CHECK_EQ_INT(frame[i], rc_frame[i]);

    crsf_parser_t p;
    crsf_parser_init(&p);
    n = crsf_build_attitude(frame, 0.1f, -0.2f, 3.0f);
    CHECK_EQ_INT(n, 10);
    CHECK_EQ_INT(frame[1], 8);
    /* pitch 0.1 rad -> 1000 = 0x03E8 big endian */
    CHECK_EQ_INT(frame[3], 0x03);
    CHECK_EQ_INT(frame[4], 0xE8);
    uint8_t type = 0;
    for (int i = 0; i < n; i++) type = crsf_parse_byte(&p, frame[i], (uint32_t)i);
    CHECK_EQ_INT(type, CRSF_TYPE_ATTITUDE);

    n = crsf_build_battery(frame, 16.8f, 12.3f, 1234, 80);
    CHECK_EQ_INT(n, 12);
    CHECK_EQ_INT((frame[3] << 8) | frame[4], 168);
    CHECK_EQ_INT((frame[5] << 8) | frame[6], 123);
    for (int i = 0; i < n; i++) type = crsf_parse_byte(&p, frame[i], (uint32_t)(100 + i));
    CHECK_EQ_INT(type, CRSF_TYPE_BATTERY);

    n = crsf_build_flight_mode(frame, "ACRO");
    CHECK_EQ_INT(n, 9);
    CHECK_EQ_INT(frame[7], 0);
}

int main(void)
{
    RUN(test_crc8_check_value);
    RUN(test_parse_rc_frame);
    RUN(test_crc_error_and_timeout);
    RUN(test_link_stats);
    RUN(test_pack_roundtrip_and_builders);
    return TT_SUMMARY();
}
